(6515515, 969006, 118154, '<td valign="top">Nice one.</td>', 'Nice one.', '2011-08-25 13:57:27.000000', NULL, 1),
(6515521, 968824, 66384, '<td valign="top">Very creative and unusual. I love the bright sunny yellow, the soft shadow, and the simplicity of design.</td>', 'Very creative and unusual. I love the bright sunny yellow, the soft shadow, and the simplicity of design.', '2011-08-25 14:02:52.000000', NULL, 1),
(6515525, 969130, 73942, '<td valign="top">nice gerbera shot, does remind me of Shez''s gerberas, not sure i''m all that crazy about the border thou</td>', 'nice gerbera shot, does remind me of Shez''s gerberas, not sure i''m all that crazy about the border thou', '2011-08-25 14:04:45.000000', NULL, 1),
(6515526, 968335, 73942, '<td valign="top">beautiful tribute, good luck in the challenge (not voting)</td>', 'beautiful tribute, good luck in the challenge (not voting)', '2011-08-25 14:05:09.000000', NULL, 1),
(6515527, 968546, 9602, '<td valign="top">Full focus on the eye would have been nice.</td>', 'Full focus on the eye would have been nice.', '2011-08-25 14:05:10.000000', NULL, 1),
(6515528, 969093, 73942, '<td valign="top">2 in 1, beautiful flower and a bee, great capture</td>', '2 in 1, beautiful flower and a bee, great capture', '2011-08-25 14:05:36.000000', NULL, 1),
(6515529, 968928, 73942, '<td valign="top">beautiful, the petals look like they are flying</td>', 'beautiful, the petals look like they are flying', '2011-08-25 14:06:45.000000', NULL, 1),
(6515533, 969000, 9602, '<td valign="top">More light on the front to get better colors would have helped.</td>', 'More light on the front to get better colors would have helped.', '2011-08-25 14:07:14.000000', NULL, 1),
(6515534, 968037, 73942, '<td valign="top">very pretty flower but the border may be a little too heavy (not voting)</td>', 'very pretty flower but the border may be a little too heavy (not voting)', '2011-08-25 14:07:15.000000', NULL, 1),
(6515539, 968933, 73942, '<td valign="top">this just pops, well done, love the color</td>', 'this just pops, well done, love the color', '2011-08-25 14:07:39.000000', NULL, 1),
(6515562, 968987, 66384, '<td valign="top">I have never observed any negativity in Shez''s photography. This is an interesting image, though, with the cheerful background behind the decay.</td>', 'I have never observed any negativity in Shez''s photography. This is an interesting image, though, with the cheerful background behind the decay.', '2011-08-25 14:13:44.000000', NULL, 1),
(6515594, 969131, 66384, '<td valign="top">Chez generally fills the frame in her images. I think this needs some color and texture for a background. The colors and design are very reminiscent of her work.</td>', 'Chez generally fills the frame in her images. I think this needs some color and texture for a background. The colors and design are very reminiscent of her work.', '2011-08-25 14:20:51.000000', NULL, 1),
(6515604, 968778, 66384, '<td valign="top">I''m sure Shez will love this. It has all the elements of her style: symmetry, texture, square crop, colors. With a border, this would have nailed it. Very nice.</td>', 'I''m sure Shez will love this. It has all the elements of her style: symmetry, texture, square crop, colors. With a border, this would have nailed it. Very nice.', '2011-08-25 14:24:20.000000', NULL, 1),
(6515643, 969092, 66384, '<td valign="top">I suspect Shez would have cropped this square -- the extra information on the bottom doesn''t add much to the image. I think the shallow DOF adds a very nice demension to this composition.</td>', 'I suspect Shez would have cropped this square -- the extra information on the bottom doesn''t add much to the image. I think the shallow DOF adds a very nice demension to this composition.', '2011-08-25 14:41:33.000000', NULL, 1),
(6515644, 968863, 66384, '<td valign="top">I really like the top two thirds of this image. I think it would be more effective without the dark green at the bottom. To me, the lines and the color of the dark green leaves are not harmonious the rest of the composition, which is quite beautiful.</td>', 'I really like the top two thirds of this image. I think it would be more effective without the dark green at the bottom. To me, the lines and the color of the dark green leaves are not harmonious the rest of the composition, which is quite beautiful.', '2011-08-25 14:41:38.000000', NULL, 1),
(6515648, 969120, 108580, '<td valign="top">Beautiful image. Subtle and yet powerful.</td>', 'Beautiful image. Subtle and yet powerful.', '2011-08-25 14:43:12.000000', NULL, 1),
(6515661, 968455, 66384, '<td valign="top">Beautiful! I love the texture and natural greens in this. Somehow, I think Shez would have pumped up the colors a bit, but I think this is a really fine image.</td>', 'Beautiful! I love the texture and natural greens in this. Somehow, I think Shez would have pumped up the colors a bit, but I think this is a really fine image.', '2011-08-25 14:49:50.000000', NULL, 1),
(6515666, 968838, 66384, '<td valign="top">Oh, I know Chez will love this bright colorful image. What nice texture and detail you got in the white.</td>', 'Oh, I know Chez will love this bright colorful image. What nice texture and detail you got in the white.', '2011-08-25 14:52:54.000000', NULL, 1),
(6515678, 968913, 66384, '<td valign="top">Very pretty colors and design in the bubble. It looks like a landscape from far above the earth, and the little white ''V'' looks like a soaring bird.</td>', 'Very pretty colors and design in the bubble. It looks like a landscape from far above the earth, and the little white ''V'' looks like a soaring bird.', '2011-08-25 15:01:45.000000', NULL, 1),
(6515687, 968573, 108580, '<td valign="top">Awesome. Thoughtful, researched and super attention to detail.</td>', 'Awesome. Thoughtful, researched and super attention to detail.', '2011-08-25 15:12:40.000000', NULL, 1),
(6515691, 969060, 66384, '<td valign="top">Definitely looks like a Sherpet. I imagine she might have used a third variety of beans for more interest.</td>', 'Definitely looks like a Sherpet. I imagine she might have used a third variety of beans for more interest.', '2011-08-25 15:15:39.000000', NULL, 1),
(6515694, 969118, 66384, '<td valign="top">Something seems less than sharp -- perhaps a bit of motion from the leaf, or camera shake. The subject, colors, crop, and border are all right in the style of Sherpet.</td>', 'Something seems less than sharp -- perhaps a bit of motion from the leaf, or camera shake. The subject, colors, crop, and border are all right in the style of Sherpet.', '2011-08-25 15:19:40.000000', NULL, 1),
(6515696, 969004, 66384, '<td valign="top">I''m straining to bring this into focus. I don''t understand why, because the small veins in the leaf seem sharp. Except for that discomfort, I like this.</td>', 'I''m straining to bring this into focus. I don''t understand why, because the small veins in the leaf seem sharp. Except for that discomfort, I like this.', '2011-08-25 15:23:28.000000', NULL, 1),
(6515698, 969006, 66384, '<td valign="top">You''ve said in an image what we all feel. :)</td>', 'You''ve said in an image what we all feel. :)', '2011-08-25 15:24:44.000000', NULL, 1),
(6515700, 969083, 108580, '<td valign="top">! Beaut abstract in B&amp;W !</td>', '! Beaut abstract in B&W !', '2011-08-25 15:28:21.000000', NULL, 1),
(6515702, 968287, 108580, '<td valign="top">Lovely portrait and composition. Feels over sharpened.</td>', 'Lovely portrait and composition. Feels over sharpened.', '2011-08-25 15:29:22.000000', NULL, 1),
(6515707, 969084, 66384, '<td valign="top">I''m not understanding how this relates to Sherpet''s style. Although there is a bright color and texture, it''s not a cheerful or beautiful image. It doesn''t seem to celebrate life, the crop is not square, although she doesn''t always use a square crop, and there is no border.</td>', 'I''m not understanding how this relates to Sherpet''s style. Although there is a bright color and texture, it''s not a cheerful or beautiful image. It doesn''t seem to celebrate life, the crop is not square, although she doesn''t always use a square crop, and there is no border.', '2011-08-25 15:33:51.000000', NULL, 1),
(6515709, 968992, 66384, '<td valign="top">The focus seems off to me. The subject and composition are perfect, though. I think with a square crop and border, this would have nailed her style.</td>', 'The focus seems off to me. The subject and composition are perfect, though. I think with a square crop and border, this would have nailed her style.', '2011-08-25 15:38:58.000000', NULL, 1),
(6515714, 968485, 66384, '<td valign="top">Dreamy. I love the softness. And the color is soothing.</td>', 'Dreamy. I love the softness. And the color is soothing.', '2011-08-25 15:41:24.000000', NULL, 1),
(6515715, 969085, 66384, '<td valign="top">Beautiful DOF and focus. Lovely texture and brilliant blue. I''m sure Shez will love this.</td>', 'Beautiful DOF and focus. Lovely texture and brilliant blue. I''m sure Shez will love this.', '2011-08-25 15:44:36.000000', NULL, 1),
(6515716, 968634, 66384, '<td valign="top">How cheerful! This really celebrates life -- the true essence of Sherpet.</td>', 'How cheerful! This really celebrates life -- the true essence of Sherpet.', '2011-08-25 15:46:20.000000', NULL, 1),
(6515717, 968939, 66384, '<td valign="top">I think with a square crop (removing the top), this would have been perfect for this challenge. As it is it is beautiful, and I wouldn''t change a thing.</td>', 'I think with a square crop (removing the top), this would have been perfect for this challenge. As it is it is beautiful, and I wouldn''t change a thing.', '2011-08-25 15:50:32.000000', NULL, 1),
(6515719, 969052, 66384, '<td valign="top">This is a beautiful flower. I think you nailed the focus and DOF. With a colored background this would be outstanding.</td>', 'This is a beautiful flower. I think you nailed the focus and DOF. With a colored background this would be outstanding.', '2011-08-25 15:58:44.000000', NULL, 1),
(6515721, 967918, 66384, '<td valign="top">The blues and greens are lovely. The composition doesn''t do much for me. I think it would be a stronger image without the left side and the top. My eye seems to be "ping-ponging" between the right and left side, and not finding a resting place.</td>', 'The blues and greens are lovely. The composition doesn''t do much for me. I think it would be a stronger image without the left side and the top. My eye seems to be "ping-ponging" between the right and left side, and not finding a resting place.', '2011-08-25 16:09:15.000000', NULL, 1),
(6515723, 969100, 66384, '<td valign="top">Looks like a Sherpet to me. I really like the painterly feel of the outer portion of this, with the natural sharpness of the interior portion. Very clever.</td>', 'Looks like a Sherpet to me. I really like the painterly feel of the outer portion of this, with the natural sharpness of the interior portion. Very clever.', '2011-08-25 16:12:52.000000', NULL, 1),
(6515728, 969096, 66384, '<td valign="top">Beauty indeed!!</td>', 'Beauty indeed!!', '2011-08-25 16:14:58.000000', NULL, 1),
(6515738, 969054, 66384, '<td valign="top">Shez might have removed the left side, making it square, but this is indeed very reminiscent of a Sherpet image. Simple, nice texture and color, and interesting curve.</td>', 'Shez might have removed the left side, making it square, but this is indeed very reminiscent of a Sherpet image. Simple, nice texture and color, and interesting curve.', '2011-08-25 16:20:50.000000', NULL, 1),
(6515743, 968311, 124982, '<td valign="top">Very, very nice take on the challenge. I like this image with the colors, shapes and textures a lot.<br/>EDIT: came back to this one. FULLY expect to see this on the front page. Just love the colors...so vibrant! I"d love to know how you processed this!</td>', 'Very, very nice take on the challenge. I like this image with the colors, shapes and textures a lot.EDIT: came back to this one. FULLY expect to see this on the front page. Just love the colors...so vibrant! I"d love to know how you processed this!', '2011-08-25 16:28:33.000000', NULL, 1),
(6515747, 969057, 108991, '<td valign="top">might have been wonderful in B&amp;W</td>', 'might have been wonderful in B&W', '2011-08-25 16:29:35.000000', NULL, 1),
(6515760, 969120, 86447, '<td valign="top">Oh.... stunningly beautiful!</td>', 'Oh.... stunningly beautiful!', '2011-08-25 17:03:39.000000', NULL, 1),
(6515761, 969091, 86447, '<td valign="top">This is so pretty... those blues make this a fabulous scene instead of a bunch of mess.</td>', 'This is so pretty... those blues make this a fabulous scene instead of a bunch of mess.', '2011-08-25 17:04:07.000000', NULL, 1),
(6515762, 968932, 86447, '<td valign="top">ohh.... lovely!   The softness of this is beautiful.</td>', 'ohh.... lovely!   The softness of this is beautiful.', '2011-08-25 17:04:33.000000', NULL, 1),
(6515763, 968634, 86447, '<td valign="top">This is soo...   so...  happy!</td>', 'This is soo...   so...  happy!', '2011-08-25 17:05:02.000000', NULL, 1),
(6515766, 968917, 86447, '<td valign="top">This is SOOooooo   Shez!   Well done!</td>', 'This is SOOooooo   Shez!   Well done!', '2011-08-25 17:06:48.000000', NULL, 1),
(6515769, 968573, 86447, '<td valign="top">This is so interesting!  I love seeing the lines through the drops.</td>', 'This is so interesting!  I love seeing the lines through the drops.', '2011-08-25 17:08:51.000000', NULL, 1),
(6515770, 968311, 86447, '<td valign="top">What WONDERFUL colors!</td>', 'What WONDERFUL colors!', '2011-08-25 17:09:10.000000', NULL, 1),
(6515771, 969108, 86447, '<td valign="top">Such a HAPPY photograph!</td>', 'Such a HAPPY photograph!', '2011-08-25 17:09:28.000000', NULL, 1),
(6515772, 969004, 86447, '<td valign="top">I really enjoy looking at this.   So much detail and the colors are wonderful.</td>', 'I really enjoy looking at this.   So much detail and the colors are wonderful.', '2011-08-25 17:10:28.000000', NULL, 1),
(6515778, 968493, 96751, '<td valign="top">Love the colors and the edges of the petals</td>', 'Love the colors and the edges of the petals', '2011-08-25 17:14:45.000000', NULL, 1),
(6515781, 969098, 86447, '<td valign="top">I really, really like the orange and pinks together (so Shez!) and the water drops set it off even better.    I really don''t like the green at all.   Perhaps blue would have been a better compliment?  Or perhaps a Sherpet Signature Square crop?</td>', 'I really, really like the orange and pinks together (so Shez!) and the water drops set it off even better.    I really don''t like the green at all.   Perhaps blue would have been a better compliment?  Or perhaps a Sherpet Signature Square crop?', '2011-08-25 17:15:47.000000', NULL, 1),
(6515782, 968846, 86447, '<td valign="top">Beautiful colors!   The centered subject would be enhanced, I think, by Sherpet''s Signature Square Crop.</td>', 'Beautiful colors!   The centered subject would be enhanced, I think, by Sherpet''s Signature Square Crop.', '2011-08-25 17:16:48.000000', NULL, 1),
(6515783, 968546, 86447, '<td valign="top">Ha!  I love the title!   I wish the eye were more in focus... but perhaps that''s what you meant to do.</td>', 'Ha!  I love the title!   I wish the eye were more in focus... but perhaps that''s what you meant to do.', '2011-08-25 17:17:40.000000', NULL, 1),
(6515784, 968900, 86447, '<td valign="top">Oh... this gets more lovely the longer I look at it.</td>', 'Oh... this gets more lovely the longer I look at it.', '2011-08-25 17:18:41.000000', NULL, 1),
(6515814, 968905, 66384, '<td valign="top">Nice detail and color. I like the crisp edges of the petals.</td>', 'Nice detail and color. I like the crisp edges of the petals.', '2011-08-25 18:04:53.000000', NULL, 1),
(6515818, 968274, 66384, '<td valign="top">Nice design and color. Perhaps if there had been a bit more curl in the papers, there would be more depth and color variation in the image. As is, it seems rather flat except on the far right edge.</td>', 'Nice design and color. Perhaps if there had been a bit more curl in the papers, there would be more depth and color variation in the image. As is, it seems rather flat except on the far right edge.', '2011-08-25 18:09:57.000000', NULL, 1),
(6515823, 968852, 66384, '<td valign="top">Very colorful and cheerful. Both Sherpet traits. :) I like the the variations of designs within the candies.</td>', 'Very colorful and cheerful. Both Sherpet traits. :) I like the the variations of designs within the candies.', '2011-08-25 18:13:34.000000', NULL, 1),
(6515825, 967987, 66384, '<td valign="top">This really pops! Marvelous.</td>', 'This really pops! Marvelous.', '2011-08-25 18:14:34.000000', NULL, 1),
(6515828, 968272, 66384, '<td valign="top">Nice capture. Cheerful!</td>', 'Nice capture. Cheerful!', '2011-08-25 18:17:37.000000', NULL, 1),
(6515834, 968916, 66384, '<td valign="top">Beautiful gradations in color. I love the composition. You didn''t square crop or add a border, but I still think you nailed this challenge.</td>', 'Beautiful gradations in color. I love the composition. You didn''t square crop or add a border, but I still think you nailed this challenge.', '2011-08-25 18:20:01.000000', NULL, 1),
(6515840, 967889, 66384, '<td valign="top">Beautiful creamy color and warmth. Beautiful composition, and graceful curves. Love it.</td>', 'Beautiful creamy color and warmth. Beautiful composition, and graceful curves. Love it.', '2011-08-25 18:23:46.000000', NULL, 1),
(6515842, 969078, 66384, '<td valign="top">Nice colors and texture.</td>', 'Nice colors and texture.', '2011-08-25 18:25:42.000000', NULL, 1),
(6515843, 968914, 66384, '<td valign="top">Beautiful bokeh and contrast.</td>', 'Beautiful bokeh and contrast.', '2011-08-25 18:26:44.000000', NULL, 1),
(6515846, 969132, 66384, '<td valign="top">I like the sunny background and the funny hairy leaves in the foreground.</td>', 'I like the sunny background and the funny hairy leaves in the foreground.', '2011-08-25 18:28:49.000000', NULL, 1),
(6515847, 968932, 66384, '<td valign="top">Exquisite color and light and focus.</td>', 'Exquisite color and light and focus.', '2011-08-25 18:30:27.000000', NULL, 1),
(6515849, 968833, 66384, '<td valign="top">I like the diagonal lines and the three points of red. Outstanding.</td>', 'I like the diagonal lines and the three points of red. Outstanding.', '2011-08-25 18:31:54.000000', NULL, 1),
(6515860, 969004, 108580, '<td valign="top">Gorgeous veins. Super light and PP.</td>', 'Gorgeous veins. Super light and PP.', '2011-08-25 18:43:28.000000', NULL, 1),
(6515861, 968939, 108580, '<td valign="top">Stunning detail. Inside it''s own light tent.</td>', 'Stunning detail. Inside it''s own light tent.', '2011-08-25 18:43:51.000000', NULL, 1),
(6515864, 968165, 108580, '<td valign="top">Lovely detail and light</td>', 'Lovely detail and light', '2011-08-25 18:44:02.000000', NULL, 1),
(6515865, 968846, 108580, '<td valign="top">Exquisite detail, contrast and light</td>', 'Exquisite detail, contrast and light', '2011-08-25 18:44:40.000000', NULL, 1);
