(6518331, 969113, 110744, '<td valign="top">Great depth of field and angle! The soft background is gorgeous!</td>', 'Great depth of field and angle! The soft background is gorgeous!', '2011-08-28 04:48:50.000000', NULL, 1),
(6518332, 968939, 110744, '<td valign="top">Amazing! What an eye you have!</td>', 'Amazing! What an eye you have!', '2011-08-28 04:49:20.000000', NULL, 1),
(6518333, 968913, 110744, '<td valign="top">Wow, lovely colors. I wish the image was a bit bigger though.</td>', 'Wow, lovely colors. I wish the image was a bit bigger though.', '2011-08-28 04:49:59.000000', NULL, 1),
(6518334, 968335, 110744, '<td valign="top">Hahaha. Way cute!</td>', 'Hahaha. Way cute!', '2011-08-28 04:50:11.000000', NULL, 1),
(6518404, 968934, 66384, '<td valign="top">I really like those circles of confusion and the warm brown background. The soft focus is nice too, although I think I would like it better with a small portion of the center flower in sharp focus.</td>', 'I really like those circles of confusion and the warm brown background. The soft focus is nice too, although I think I would like it better with a small portion of the center flower in sharp focus.', '2011-08-28 09:28:35.000000', NULL, 1),
(6518407, 968844, 135937, '<td valign="top">How clever!!!!!! I love this concept!</td>', 'How clever!!!!!! I love this concept!', '2011-08-28 09:29:23.000000', NULL, 1),
(6518411, 968839, 66384, '<td valign="top">Very pretty composition and contrast. I like the soft green too.</td>', 'Very pretty composition and contrast. I like the soft green too.', '2011-08-28 09:34:27.000000', NULL, 1),
(6518413, 969113, 66384, '<td valign="top">Very cheerful. I like the shallow DOF and the brown bokeh.</td>', 'Very cheerful. I like the shallow DOF and the brown bokeh.', '2011-08-28 09:36:28.000000', NULL, 1),
(6518417, 968794, 66384, '<td valign="top">I think noise reduction would improve the background which has a very nice bokeh. Nice job capturing that bee.</td>', 'I think noise reduction would improve the background which has a very nice bokeh. Nice job capturing that bee.', '2011-08-28 09:42:50.000000', NULL, 1),
(6518419, 968834, 66384, '<td valign="top">What a lovely collection! Beautiful job catching the detail, color, and clarity of the glass.</td>', 'What a lovely collection! Beautiful job catching the detail, color, and clarity of the glass.', '2011-08-28 09:47:13.000000', NULL, 1),
(6518422, 969120, 66384, '<td valign="top">LOVE these colors, the DOF, and composition. It''s dreamy.</td>', 'LOVE these colors, the DOF, and composition. It''s dreamy.', '2011-08-28 09:50:51.000000', NULL, 1),
(6518424, 969110, 66384, '<td valign="top">If this were mine, I''d crop it close to eliminate the background. The little drop of water would show up better too. I really like the colors of the plant.</td>', 'If this were mine, I''d crop it close to eliminate the background. The little drop of water would show up better too. I really like the colors of the plant.', '2011-08-28 09:59:55.000000', NULL, 1),
(6518427, 969106, 66384, '<td valign="top">Oh, nice rhythm, light and color.</td>', 'Oh, nice rhythm, light and color.', '2011-08-28 10:01:10.000000', NULL, 1),
(6518429, 968546, 66384, '<td valign="top">I would like this better if the eye was in sharp focus. The DOF seems a little too shallow for this subject. I like the colors and composition.</td>', 'I would like this better if the eye was in sharp focus. The DOF seems a little too shallow for this subject. I like the colors and composition.', '2011-08-28 10:06:36.000000', NULL, 1),
(6518432, 969101, 135937, '<td valign="top">Green and pink go so well together. This is beautiful!</td>', 'Green and pink go so well together. This is beautiful!', '2011-08-28 10:07:50.000000', NULL, 1),
(6518436, 969057, 66384, '<td valign="top">Outstanding texture, contrast, and rich color. I like the off center composition and the graceful curves.</td>', 'Outstanding texture, contrast, and rich color. I like the off center composition and the graceful curves.', '2011-08-28 10:09:41.000000', NULL, 1),
(6518438, 969014, 66384, '<td valign="top">Pretty colors and bokeh. I think if the left half were cropped off to create a square, you would have a stronger image, featuring the beautiful focus on the wet leaf and the graceful curves in the lower right corner.</td>', 'Pretty colors and bokeh. I think if the left half were cropped off to create a square, you would have a stronger image, featuring the beautiful focus on the wet leaf and the graceful curves in the lower right corner.', '2011-08-28 10:16:40.000000', NULL, 1),
(6518449, 969098, 117804, '<td valign="top">so delicate... A touch of noise reduction would have improved the image yet.</td>', 'so delicate... A touch of noise reduction would have improved the image yet.', '2011-08-28 10:51:46.000000', NULL, 1),
(6518450, 968335, 117804, '<td valign="top">That''s a cool tribute to Shez and her artform :-)</td>', 'That''s a cool tribute to Shez and her artform :-)', '2011-08-28 10:53:08.000000', NULL, 1),
(6518452, 968495, 117804, '<td valign="top">nice arrangement...</td>', 'nice arrangement...', '2011-08-28 10:58:59.000000', NULL, 1),
(6518453, 969100, 117804, '<td valign="top">Really like the idea</td>', 'Really like the idea', '2011-08-28 10:59:37.000000', NULL, 1),
