(6518532, 968852, 98291, '<td valign="top">I love these colours! Very awesome</td>', 'I love these colours! Very awesome', '2011-08-28 12:53:50.000000', NULL, 1),
(6518533, 969131, 98291, '<td valign="top">Very very creative</td>', 'Very very creative', '2011-08-28 12:54:13.000000', NULL, 1),
(6518534, 968824, 98291, '<td valign="top">Very interesting! I''m a little confused</td>', 'Very interesting! I''m a little confused', '2011-08-28 12:55:08.000000', NULL, 1),
(6518535, 969100, 98291, '<td valign="top">Very unique and creative!</td>', 'Very unique and creative!', '2011-08-28 12:55:38.000000', NULL, 1),
(6518536, 968335, 98291, '<td valign="top">Wow, you''re using almost all of sherpet''s styles in here. But the background should have been different.</td>', 'Wow, you''re using almost all of sherpet''s styles in here. But the background should have been different.', '2011-08-28 12:56:53.000000', NULL, 1),
(6518540, 968844, 98291, '<td valign="top">Cool, someone who took the pencil idea. My friend had the idea to do something with pencils aswell, but didn''t manage to get the right shot, so she didn''t enter. I think you did a good job, but could''ve done better on some points.</td>', 'Cool, someone who took the pencil idea. My friend had the idea to do something with pencils aswell, but didn''t manage to get the right shot, so she didn''t enter. I think you did a good job, but could''ve done better on some points.', '2011-08-28 12:59:28.000000', NULL, 1),
(6518851, 969108, 70484, '<td valign="top">I think the picture is beautiful and I love it!!! However, I am not a fan of the frame.</td>', 'I think the picture is beautiful and I love it!!! However, I am not a fan of the frame.', '2011-08-29 00:10:23.000000', NULL, 1),
(6518855, 968933, 70484, '<td valign="top">Stunning!!!! I love this picture!</td>', 'Stunning!!!! I love this picture!', '2011-08-29 00:11:48.000000', NULL, 1),
(6518864, 969120, 70484, '<td valign="top">The colors are beautiful here. Love it!</td>', 'The colors are beautiful here. Love it!', '2011-08-29 00:13:18.000000', NULL, 1),
(6519080, 968574, 125275, '<td valign="top">I like how the colors in the border complement the background.</td>', 'I like how the colors in the border complement the background.', '2011-08-29 02:04:34.000000', NULL, 1),
(6519081, 968863, 125275, '<td valign="top">Very colorful and sharp.</td>', 'Very colorful and sharp.', '2011-08-29 02:04:55.000000', NULL, 1),
(6519082, 968634, 125275, '<td valign="top">This really brings out the beauty and depth in the yellow. Well done.</td>', 'This really brings out the beauty and depth in the yellow. Well done.', '2011-08-29 02:05:21.000000', NULL, 1),
(6519085, 969081, 125275, '<td valign="top">If this is tone-mapped, it feels a little heavy. Still, I think the brightness of the stalk and the cropping work really well.</td>', 'If this is tone-mapped, it feels a little heavy. Still, I think the brightness of the stalk and the cropping work really well.', '2011-08-29 02:06:06.000000', NULL, 1),
(6519091, 969098, 125275, '<td valign="top">This is incredibly beautiful. A square crop might be "more sherpet," but who am I to complain about this picture? I can''t. 8</td>', 'This is incredibly beautiful. A square crop might be "more sherpet," but who am I to complain about this picture? I can''t. 8', '2011-08-29 02:07:23.000000', NULL, 1),
(6519092, 969121, 125275, '<td valign="top">Very nice colors.</td>', 'Very nice colors.', '2011-08-29 02:07:26.000000', NULL, 1),
(6519093, 969016, 125275, '<td valign="top">This is a really cool looking macro. Who knew there could be so much variance of texture, color and lighting in a wire mesh.</td>', 'This is a really cool looking macro. Who knew there could be so much variance of texture, color and lighting in a wire mesh.', '2011-08-29 02:08:35.000000', NULL, 1),
(6519095, 969129, 125275, '<td valign="top">Beautiful soft textures. I''ve said it before, but I''ll say it again: In pictures like this, of the more "artistic" and "black &amp; white" variety, it helps <i>so much</i> to have <i>any</i> part of the image in focus. That this is done here works magic for this image.</td>', 'Beautiful soft textures. I''ve said it before, but I''ll say it again: In pictures like this, of the more "artistic" and "black & white" variety, it helps so much to have any part of the image in focus. That this is done here works magic for this image.', '2011-08-29 02:10:19.000000', NULL, 1),
(6519096, 969127, 125275, '<td valign="top">Very nice colors.</td>', 'Very nice colors.', '2011-08-29 02:10:33.000000', NULL, 1),
(6519098, 968998, 125275, '<td valign="top">Beautiful perspective and nice macro.</td>', 'Beautiful perspective and nice macro.', '2011-08-29 02:10:51.000000', NULL, 1),
(6519102, 967987, 125275, '<td valign="top">Very nice clarity and colors. The saturation is the perfect amount, heavy, but not too heavy. Nicely done.</td>', 'Very nice clarity and colors. The saturation is the perfect amount, heavy, but not too heavy. Nicely done.', '2011-08-29 02:11:39.000000', NULL, 1),
(6519104, 969119, 125275, '<td valign="top">Beautiful. The plant seems to be growing and emitting light like a fragrance. Beautiful shot.</td>', 'Beautiful. The plant seems to be growing and emitting light like a fragrance. Beautiful shot.', '2011-08-29 02:12:12.000000', NULL, 1),
(6519105, 967918, 125275, '<td valign="top">Very nice use of DOF and colors.</td>', 'Very nice use of DOF and colors.', '2011-08-29 02:12:32.000000', NULL, 1),
(6519107, 968037, 125275, '<td valign="top">The border works well here, it really brightens up the flower. Nice image.</td>', 'The border works well here, it really brightens up the flower. Nice image.', '2011-08-29 02:12:59.000000', NULL, 1),
(6519108, 969101, 125275, '<td valign="top">Interesting take! Nice use of color.</td>', 'Interesting take! Nice use of color.', '2011-08-29 02:13:19.000000', NULL, 1),
(6519113, 969106, 125275, '<td valign="top">I count IIIIIIIII, but I guess you''re right. Haha, nice shot. I really like this!</td>', 'I count IIIIIIIII, but I guess you''re right. Haha, nice shot. I really like this!', '2011-08-29 02:14:19.000000', NULL, 1),
(6519114, 969113, 125275, '<td valign="top">Very nice use of depth of field and composition.</td>', 'Very nice use of depth of field and composition.', '2011-08-29 02:14:44.000000', NULL, 1),
(6519116, 968916, 125275, '<td valign="top">I like the lighting in this.</td>', 'I like the lighting in this.', '2011-08-29 02:15:30.000000', NULL, 1),
(6519172, 967889, 133234, '<td valign="top"><strike></strike></td>', '', '2011-08-29 02:56:05.000000', NULL, 1),
(6519308, 968311, 128323, '<td valign="top">The colors in this are almost surreal... awesome shot!</td>', 'The colors in this are almost surreal... awesome shot!', '2011-08-29 07:46:18.000000', NULL, 1),
(6519311, 968639, 128323, '<td valign="top">Great shot!  I love how the staircase "floats" up to the first tank.</td>', 'Great shot!  I love how the staircase "floats" up to the first tank.', '2011-08-29 07:48:00.000000', NULL, 1),
(6519312, 969006, 128323, '<td valign="top">Yikes--that looks sticky!</td>', 'Yikes--that looks sticky!', '2011-08-29 07:48:44.000000', NULL, 1),
(6519490, 968908, 66384, '<td valign="top">I like this collage effect. Nice bright colors and bold patterns too. The red on the little horse looks like it could be toned down a bit. Since the eye goes there first, right away I noticed the red was blown out.</td>', 'I like this collage effect. Nice bright colors and bold patterns too. The red on the little horse looks like it could be toned down a bit. Since the eye goes there first, right away I noticed the red was blown out.', '2011-08-29 12:09:28.000000', NULL, 1),
(6519491, 968774, 66384, '<td valign="top">Very nice light and texture. Nice pattern, and I like the simplicity.</td>', 'Very nice light and texture. Nice pattern, and I like the simplicity.', '2011-08-29 12:11:27.000000', NULL, 1),
(6519495, 968844, 66384, '<td valign="top">That''s really clever. At first I wondered why the sharpened was there, but is only took a moment to recognize the zipper. Carefully constructed and colorful -- two important elements of Sherpet''s style.</td>', 'That''s really clever. At first I wondered why the sharpened was there, but is only took a moment to recognize the zipper. Carefully constructed and colorful -- two important elements of Sherpet''s style.', '2011-08-29 12:16:14.000000', NULL, 1),
(6519499, 969075, 66384, '<td valign="top">Very interesting to have the color of the background so similar to the subject -- quite risky, but I think you made it work with the strong patterns. Nice.</td>', 'Very interesting to have the color of the background so similar to the subject -- quite risky, but I think you made it work with the strong patterns. Nice.', '2011-08-29 12:20:21.000000', NULL, 1),
(6519507, 969128, 66384, '<td valign="top">So firey and alive, and full of enthusiasm -- just like Sherpet. :) Nice the way the lines of the background follow the lines of the subject.</td>', 'So firey and alive, and full of enthusiasm -- just like Sherpet. :) Nice the way the lines of the background follow the lines of the subject.', '2011-08-29 12:24:24.000000', NULL, 1),
(6519511, 969127, 66384, '<td valign="top">Ha! Devine colors. I am going to try that; I have one of those plants by my house. Good title too.</td>', 'Ha! Devine colors. I am going to try that; I have one of those plants by my house. Good title too.', '2011-08-29 12:28:49.000000', NULL, 1),
(6519515, 969081, 66384, '<td valign="top">Pretty light on those leaves, and good colors.</td>', 'Pretty light on those leaves, and good colors.', '2011-08-29 12:30:42.000000', NULL, 1),
(6519516, 968311, 66384, '<td valign="top">It has the curves and colors and patterns that Sherpet loves. Great job!</td>', 'It has the curves and colors and patterns that Sherpet loves. Great job!', '2011-08-29 12:32:39.000000', NULL, 1),
(6519525, 968573, 66384, '<td valign="top">Ah, so carefully done, and so cheerful. I know this made Sherpet smile. I love the way you have the colors dripping and swirling out of the flower design. It''s a flower, it''s a pinwheel, it''s a rainbow, it''s brilliant!</td>', 'Ah, so carefully done, and so cheerful. I know this made Sherpet smile. I love the way you have the colors dripping and swirling out of the flower design. It''s a flower, it''s a pinwheel, it''s a rainbow, it''s brilliant!', '2011-08-29 12:39:15.000000', NULL, 1),
(6519530, 968816, 66384, '<td valign="top">I like this, but I don''t see Sherpet''s style here. Still I give you credit for the color and subject.</td>', 'I like this, but I don''t see Sherpet''s style here. Still I give you credit for the color and subject.', '2011-08-29 12:42:31.000000', NULL, 1),
(6519532, 969121, 66384, '<td valign="top">Sherpet''s subject, colors, and crop. For me, the DOF is a bit too shallow. I don''t find the focal point significant enough to carry the image.</td>', 'Sherpet''s subject, colors, and crop. For me, the DOF is a bit too shallow. I don''t find the focal point significant enough to carry the image.', '2011-08-29 12:46:46.000000', NULL, 1),
(6519534, 968037, 66384, '<td valign="top">Beautiful blossom, beautifully captured and presented.</td>', 'Beautiful blossom, beautifully captured and presented.', '2011-08-29 12:48:51.000000', NULL, 1),
(6519553, 968191, 66384, '<td valign="top">Terrific detail. So difficult to do, ''cause those little buggers just don''t hold still fi long. I really like the tones in the green and mauve petals of the thistle.</td>', 'Terrific detail. So difficult to do, ''cause those little buggers just don''t hold still fi long. I really like the tones in the green and mauve petals of the thistle.', '2011-08-29 13:03:29.000000', NULL, 1),
(6519556, 968928, 66384, '<td valign="top">Looks to me like the extreme close-ups of sun flares. Nice complementary colors and I like the crop.</td>', 'Looks to me like the extreme close-ups of sun flares. Nice complementary colors and I like the crop.', '2011-08-29 13:07:02.000000', NULL, 1),
(6519560, 968982, 66384, '<td valign="top">What a Devine bag! Nice patterns and light in this image. I like the DOF you used here.</td>', 'What a Devine bag! Nice patterns and light in this image. I like the DOF you used here.', '2011-08-29 13:09:37.000000', NULL, 1),
(6519573, 969013, 66384, '<td valign="top">Perhaps a little too much competing for attention in this image. This might benefit from one of Sherpet''s signature square crops. Still I really like your subject and colors.</td>', 'Perhaps a little too much competing for attention in this image. This might benefit from one of Sherpet''s signature square crops. Still I really like your subject and colors.', '2011-08-29 13:16:47.000000', NULL, 1),
(6519576, 969119, 66384, '<td valign="top">Lovely colors, curves, and texture. Such an unusual choice for the light -- having the centers of the blossoms in shadow, but I think it works here. This is lovely.</td>', 'Lovely colors, curves, and texture. Such an unusual choice for the light -- having the centers of the blossoms in shadow, but I think it works here. This is lovely.', '2011-08-29 13:20:16.000000', NULL, 1),
(6519577, 969094, 66384, '<td valign="top">Very Sherpet: the subject, color and texture. I like the silver and copper.</td>', 'Very Sherpet: the subject, color and texture. I like the silver and copper.', '2011-08-29 13:22:20.000000', NULL, 1),
(6519583, 969099, 66384, '<td valign="top">Beautiful. Exquisite colors and focus against that dark background. I find the broken stem competing for attention. If this were my image, I''d probably remove it.</td>', 'Beautiful. Exquisite colors and focus against that dark background. I find the broken stem competing for attention. If this were my image, I''d probably remove it.', '2011-08-29 13:31:10.000000', NULL, 1),
(6519586, 968919, 66384, '<td valign="top">Mmmmm, now this is the way to do it! Absolute perfection in all aspects.</td>', 'Mmmmm, now this is the way to do it! Absolute perfection in all aspects.', '2011-08-29 13:32:46.000000', NULL, 1),
(6519589, 968538, 66384, '<td valign="top">Beautiful detail and nice pattern, especially in the center of the flower.</td>', 'Beautiful detail and nice pattern, especially in the center of the flower.', '2011-08-29 13:35:31.000000', NULL, 1),
(6519590, 968147, 66384, '<td valign="top">Nice capture, and I like the way the colors of the bird and environment meld.</td>', 'Nice capture, and I like the way the colors of the bird and environment meld.', '2011-08-29 13:38:20.000000', NULL, 1),
(6519591, 969083, 66384, '<td valign="top">Can''t get much more Sherpet than this!</td>', 'Can''t get much more Sherpet than this!', '2011-08-29 13:40:06.000000', NULL, 1),
(6519651, 968916, 12611, '<td valign="top">beautiful shapes!</td>', 'beautiful shapes!', '2011-08-29 14:47:59.000000', NULL, 1),
